import { Form, toast } from "march/ui"
import { schema } from "march/schema"

// pizza siparişi: tek tanımdan form; boy segmentli seçim, malzemeler çoklu, ekstra peynir anahtar
const Pizza = schema({
  size: { type: "pick", label: "Boy", options: ["Küçük", "Orta", "Büyük"], default: "Orta", control: "segmented" },
  toppings: { type: "multi", label: "Malzemeler", options: ["Mantar", "Zeytin", "Mısır", "Biber", "Sucuk"] },
  cheese: { type: "bool", label: "Ekstra peynir 🧀", control: "switch" },
  note: { type: "textarea", label: "Not", max: 120, help: "Zil bozuk, kapıyı çalın gibi" },
})

export function PizzaOrder() {
  return <Form schema={Pizza} submitLabel="Sipariş ver 🍕"
    onSubmit={(v: Record<string, unknown>) => { toast(`${v.size} pizza yolda! ${(v.toppings as string[]).join(", ") || "sade"}`, { kind: "success" }) }} />
}

import { Form, Card, toast } from "march/ui"
import { schema } from "march/schema"

// kayıt formu: koşullu alanlar (plan = ekip), canlı doğrulama, gönderimde yükleniyor; sunucu hatası alanın altına düşer
// (deneyin: e-posta "...@taken.com" ile bitsin)
const SignUpForm = schema({
  name: { type: "text", label: "Ad soyad", required: true, max: 60, autocomplete: "name" },
  email: { type: "email", label: "E-posta", required: true },
  password: { type: "password", label: "Parola", required: true, min: 10, autocomplete: "new-password", help: "En az 10 karakter" },
  plan: { type: "pick", label: "Plan", options: [{ value: "free", label: "Ücretsiz" }, { value: "team", label: "Ekip" }], default: "team", control: "segmented" },
  seats: { type: "int", label: "Koltuk", min: 2, max: 500, default: 5, when: (v: Record<string, unknown>) => v.plan === "team" },
  budget: { type: "money", label: "Aylık bütçe", currency: "TRY", when: (v: Record<string, unknown>) => v.plan === "team" },
  newsletter: { type: "bool", label: "Ürün haberlerini gönder", control: "switch" },
})

export function SignUp() {
  return <Card title="Hesap oluştur">
    <Form schema={SignUpForm} layout="grid" cols={2} submitLabel="Hesap oluştur"
      onSubmit={async (v: Record<string, unknown>) => {
        await new Promise((r) => setTimeout(r, 700))
        if (String(v.email).endsWith("@taken.com")) throw Object.assign(new Error("Reddedildi"), { fieldErrors: { email: "Bu adres zaten kayıtlı" } })
        toast(`Hoş geldin, ${v.name}!`, { kind: "success" })
      }} />
  </Card>
}

import { Form, Card, Button } from "march/ui"
import { schema } from "march/schema"

// Form'un bütün özellikleri: schema, initial, onSubmit, validateOn, onChange, submitLabel, cancel, cancelLabel,
// sections, actions, confirmLeave, requireDirty, readonly, onReady, extraActions, layout, cols, class
const Profile = schema({
  name: { type: "text", label: "Ad", required: true },
  city: { type: "pick", label: "Şehir", options: ["İstanbul", "Ankara", "İzmir"] },
  birthday: { type: "date", label: "Doğum günü" },
  color: { type: "color", label: "Sevdiğin renk" },
  bio: { type: "textarea", label: "Hakkında", max: 200 },
  public: { type: "bool", label: "Profil herkese açık", control: "switch" },
})

export function FormLab() {
  let $saved = "—"
  let $changes = 0
  let $ready = "hayır"
  let $locked = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <Form class="lab-form" schema={Profile} initial={{ name: "Ece", city: "İzmir" }} validateOn="change"
      onChange={() => { $changes++ }} onReady={() => { $ready = "evet" }}
      onSubmit={(v: Record<string, unknown>) => { $saved = `${v.name} · ${v.city}` }}
      submitLabel="Kaydet" cancel cancelLabel="Vazgeç" requireDirty confirmLeave readonly={$locked}
      sections={[{ title: "Kimlik", fields: ["name", "city", "birthday"] }, { title: "Görünüm", description: "Profilinde gösterilir", fields: ["color", "bio", "public"], cols: 1 }]}
      layout="grid" cols={2}
      extraActions={<Button class="lab-lock" variant="ghost" on:click={() => { $locked = !$locked }}>{$locked ? "Kilidi aç" : "Kilitle"}</Button>} />
    <p class="lab-state" sx={{ text: "sm", color: "muted" }}>Kaydedilen: {$saved} · değişiklik: {$changes} · hazır: {$ready}</p>
    <Card m:theme="night">
      <Form class="lab-plain" schema={{ code: { type: "text", label: "Davet kodu", required: true, min: 6 } }} actions={false} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { FormLab } from "./FormLab.tsx"

// FormLab'in testleri: kaydedince Testler sekmesinde çalışır
test("şemadaki alanlar bölümleriyle çizilir; başlangıç değerleri dolu", () => {
  const s = renderTest(() => <FormLab />)
  expect(s.sees("Kimlik")).toBe(true)
  expect(s.sees("Profilinde gösterilir")).toBe(true)
  expect((s.get(".lab-form [name=name]") as HTMLInputElement).value).toBe("Ece")
  expect(s.sees("hazır: evet")).toBe(true)
})

test("değişmeden kaydedilemez (requireDirty); değişince kaydedilir", async () => {
  const s = renderTest(() => <FormLab />)
  const save = s.find("Kaydet")!.closest("button") as HTMLButtonElement
  expect(save.disabled).toBe(true)
  await s.type(s.get(".lab-form [name=name]")!, "Deniz")
  expect(s.sees("değişiklik: 0")).toBe(false)
  await s.click(save)
  await s.wait(() => s.sees("Kaydedilen: Deniz · İzmir"))
  expect(s.sees("Kaydedilen: Deniz · İzmir")).toBe(true)
})

test("zorunlu alan boşalınca hata gösterir (validateOn change)", async () => {
  const s = renderTest(() => <FormLab />)
  await s.type(s.get(".lab-form [name=name]")!, "")
  expect(s.get(".lab-form [name=name]")!.getAttribute("aria-invalid")).toBe("true")
})

test("actions={false}: düğme yok", () => {
  const s = renderTest(() => <FormLab />)
  expect(s.get(".lab-plain button[type=submit]")).toBe(null)
})
